class Solution {
public:
    int minSwapsCouples(vector<int>& row) {
        int n = row.size(), res = 0;
        unordered_map<int, int> pos;
        for (int i = 0; i < n; ++i)
            pos[row[i]] = i;
        for (int i = 0; i < n; i += 2) {
            int x = row[i];
            int y = x ^ 1;
            if (row[i + 1] != y) {
                ++res;
                int j = pos[y];
                swap(row[i + 1], row[j]);
                pos[row[j]] = j;
                pos[row[i + 1]] = i + 1;
            }
        }
        return res;
    }
};
